"""Harder random plan instances vs brute force."""
import itertools, json, random, sys
sys.path.insert(0, '/workspace/tmp')
from harness import run
from fuzz_plan import benefit_of, brute

def make_case(rng):
    nnodes = rng.randint(2, 8)
    nodes = ['n%d' % i for i in range(nnodes)]
    caps = {n: rng.choice([0,1,1,1,2,2,3,4,8]) for n in nodes}
    nflows = rng.randint(1, 13)
    flows = []
    for i in range(nflows):
        k = rng.randint(2, min(6, nnodes))
        # bias towards shared nodes
        if rng.random() < 0.7 and nnodes >= 3:
            path = [rng.choice(nodes[:max(3,nnodes)]) for _ in range(k)]
            seen=[]; 
            for p in path:
                if p not in seen: seen.append(p)
            path = seen
            if len(path) < 2:
                path = rng.sample(nodes, 2)
        else:
            path = rng.sample(nodes, k)
        H = rng.randint(8, 16)
        while True:
            kinds = list('KDZQT') + [rng.choice('KDZ') for _ in range(H - 5)]
            rng.shuffle(kinds)
            nd = kinds.count('D')
            if kinds.count('K') >= 1 and 4 + nd < H:
                break
        template = bytes(rng.randrange(256) for _ in range(H))
        flows.append({'id': 'f%d' % i, 'path': path,
                      'template': template.hex(), 'kinds': ''.join(kinds)})
    offers = {}
    for f in flows:
        H = len(f['template']) // 2
        kinds = f['kinds']; path = f['path']
        runs = []
        for _ in range(rng.randint(0, 3)):
            hb = bytearray(rng.randrange(256) for _ in range(H))
            if rng.random() < 0.75:
                for pos, c in enumerate(kinds):
                    if c == 'K':
                        hb[pos] = int(f['template'][2*pos:2*pos+2], 16)
                    elif c == 'Q':
                        hb[pos] = rng.choice([0,3,7,8,9])
                    elif c == 'T':
                        hb[pos] = rng.choice([0,1,len(path)-1,len(path),len(path)+1,255])
            runs.append({'header': bytes(hb).hex(), 'count': rng.randint(1, 20)})
        offers[f['id']] = runs
    pinned = [f['id'] for f in flows if rng.random() < 0.15]
    return {'mode':'plan','capacities':caps,'flows':flows,'warmup':rng.choice([0,1,5,20]),
            'pinned':pinned,'offers':offers}

def main():
    rng = random.Random(int(sys.argv[1]))
    n = int(sys.argv[2])
    reqs = [make_case(rng) for _ in range(n)]
    got = run(reqs)
    bad = 0
    for req, g in zip(reqs, got):
        exp = brute(req)
        if g != exp:
            bad += 1
            print('MISMATCH')
            print(json.dumps(req))
            print('got', json.dumps(g, sort_keys=True))
            print('exp', json.dumps(exp, sort_keys=True))
            if bad > 2: break
    print('cases', n, 'mismatches', bad)

main()
